<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card"><div class="card-header"><h1>Delivery Assign & Status</h1><p>Take pending orders and update delivery state.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$orders):?><p class="muted">No orders yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Customer</th><th>Amount</th><th>Status</th><th>Assigned To</th><th>Date</th><th>Update</th></tr><?php foreach($orders as $o): $mine=(int)$o['assigned_vendor_id']===$vid;?><tr style="<?php echo $mine?'background:#eef0ff;':'';?>"><td>#<?php echo e($o['id']);?></td><td><?php echo e($o['customer_name']);?></td><td>TK <?php echo e(number_format((float)$o['total_amount'],2));?></td><td><?php echo e($o['delivery_status']);?></td><td><?php echo $o['vendor_name']?e($o['vendor_name']):'<span class="muted">unassigned</span>';?></td><td class="small"><?php echo e($o['created_at']);?></td><td><form method="post" action="<?php echo e(url_for('vendor','delivery'));?>"><?php echo csrf_field();?><input type="hidden" name="order_id" value="<?php echo e($o['id']);?>"><select name="delivery_status"><?php foreach(['pending','shipped','delivered','cancelled'] as $s):?><option value="<?php echo e($s);?>" <?php echo $o['delivery_status']===$s?'selected':'';?>><?php echo e($s);?></option><?php endforeach;?></select><label class="small"><input type="checkbox" name="assign_to_me" value="1" <?php echo $mine?'checked':'';?>> assign to me</label><button class="btn btn-primary btn-small">Save</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
